describe('Skip Navigation Link Focus Behavior', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should make skip navigation link the first focusable element when page loads', () => {
    // Verify skip link is visible and has tabindex
    cy.get('[data-testid="skip-nav-link"]').should('be.visible');
    cy.get('[data-testid="skip-nav-link"]').should('have.attr', 'tabindex', '-1');

    // Verify skip link is focused on page load
    cy.get('[data-testid="skip-nav-link"]').should('have.focus');

    // Verify first focusable element is the skip link
    cy.get('[data-testid="first-focusable-element"]').should('not.exist');
    cy.get('[data-testid="skip-nav-link"]').should('have.attr', 'aria-label', 'Skip to main content');

    // Verify skip link has correct aria attributes
    cy.get('[data-testid="skip-nav-link"]').should('have.attr', 'aria-hidden', 'false');
    cy.get('[data-testid="skip-nav-link"]').should('have.attr', 'role', 'navigation');
  });

  it('should maintain focus on skip link when navigating through keyboard', () => {
    // Navigate to skip link using keyboard
    cy.get('[data-testid="skip-nav-link"]').click();

    // Verify skip link remains focused
    cy.get('[data-testid="skip-nav-link"]').should('have.focus');

    // Verify skip link is still the first focusable element
    cy.get('[data-testid="first-focusable-element"]').should('not.exist');

    // Navigate back to main content using keyboard
    cy.get('[data-testid="skip-nav-link"]').click();

    // Verify focus returns to main content
    cy.get('[data-testid="main-content"]').should('have.focus');

    // Verify skip link is still visible and accessible
    cy.get('[data-testid="skip-nav-link"]').should('be.visible');
  });
});
